#!/bin/sh
# boxwake-unit.t.sh: goal:g7.16.1.11.32 (DG1 10-11): the static lanes of the box-wake unit. sh + grep + sed on a TREE, no git, no network, no root, no systemd, 0 USD.
# ROOT=<tree> (or $1) = the tree whose .agi/nodes/.geometry/engine*.md is read; UNIT_FILE=<file> tests a MUTATED copy of the `### agi-boxwake@.service` fenced body, POST_FILE=<file> a mutated agi-post@.service body, RUN_FILE=<file> a mutated agi-run body.
# F1  engine-wrap.md holds no `while sleep` (a killed or failed sleep ends such a loop for good and nothing restarted it).
# F3  the unit carries what makes a re-spawned loop the SAME loop: User=agi-%i, PartOf= + After= the post, Restart=on-failure, RestartSec=10s, RestartForceExitStatus=SIGTERM SIGHUP SIGINT SIGPIPE (a TERM/HUP/INT/PIPE is a CLEAN exit to systemd: a pkill of the group would leave the loop dead), the pane fifo %t/agi-%i/i, WorkingDirectory=/var/lib/agi/%i/t (box reads ~/t), EnvironmentFile=-/var/lib/agi/%i.env, AGI_POST=%i and PATH= in the unit's own Environment, NO AGI_SEAT (goal:g7.16.1.11.37), and an ExecCondition that gates on the harness with NO brace (systemd would substitute ${H} with a value that holds spaces for a pi post, `case` then fails to parse, dash exits 2 and EVERY claude post would be skipped); the post unit WANTS the wake unit.
# F4a anti-vacuous: F1 is also met by DELETING the loop, and a converted loop PLUS the unit is a double wake: the unit EXISTS and carries exactly ONE `box n` loop, agi-run carries ZERO, and the loop never ends on its own (`sleep N||:`).
# F5  no heartbeat file and no checker unit in engine-root.md / engine-wrap.md (systemd is the detector and the re-spawner).
R0=${ROOT:-${1:-$(cd "$(dirname "$0")/../../.." && pwd)}};G=$R0/.agi/nodes/.geometry;f=0;T=$(mktemp -d);trap 'rm -rf $T' 0
sect(){ cat $G/engine*.md|sed -n "/^###* $1 /,/^###* /{/^~~~/,/^~~~/{//!p}}";}
ok(){ if eval "$2";then echo "ok $1";else echo "FAIL $1";f=$((f+1));fi;}
sect agi-boxwake@.service>$T/u;sect agi-post@.service>$T/p;sect agi-run>$T/ar
[ -z "$UNIT_FILE" ]||cp "$UNIT_FILE" $T/u;[ -z "$POST_FILE" ]||cp "$POST_FILE" $T/p;[ -z "$RUN_FILE" ]||cp "$RUN_FILE" $T/ar
[ -s $T/p ]&&[ -s $T/ar ]&&[ -s $T/u ]||{ echo "FAIL extract: wake unit $(wc -c<$T/u) B, post unit $(wc -c<$T/p) B, agi-run $(wc -c<$T/ar) B";exit 99;}
has(){ grep -qxF -- "$1" $T/u;}
nws=$(grep -c 'while sleep' $G/engine-wrap.md);nwa=$(grep -c 'while sleep' $T/ar)
ok "f1-no-while-sleep-in-engine-wrap engine-wrap.md holds $nws 'while sleep' (want 0), the agi-run piece $nwa (want 0)" '[ "$nws" = 0 ]&&[ "$nwa" = 0 ]'
for l in 'User=agi-%i' 'PartOf=agi-post@%i.service' 'After=agi-post@%i.service' 'Restart=on-failure' 'RestartSec=10s' 'RestartForceExitStatus=SIGTERM SIGHUP SIGINT SIGPIPE' 'WorkingDirectory=/var/lib/agi/%i/t' 'EnvironmentFile=-/var/lib/agi/%i.env';do
 ok "f3-unit-carries-$(echo "$l"|cut -d= -f1)-$(echo "$l"|cut -d= -f2-|tr -c 'A-Za-z0-9\n' _|cut -c1-24) the unit holds the exact line [$l]" 'has "$l"';done
ok "f3-unit-names-the-pane-fifo the ExecStart writes the post's pane fifo %t/agi-%i/i ($(grep -c '^ExecStart=.*%t/agi-%i/i' $T/u) ExecStart line(s) with it, want 1)" '[ "$(grep -c "^ExecStart=.*%t/agi-%i/i" $T/u)" = 1 ]'
ok "f3-unit-environment-has-AGI_POST-and-PATH-and-no-AGI_SEAT the unit's own Environment= lines: AGI_POST=%i $(grep '^Environment=' $T/u|grep -c 'AGI_POST=%i') (want 1), PATH= $(grep '^Environment=' $T/u|grep -c ' *PATH=\|=PATH=\|^Environment=PATH=') (want >= 1), AGI_SEAT anywhere in the unit: $(grep -c AGI_SEAT $T/u) (want 0)" '[ "$(grep "^Environment=" $T/u|grep -c "AGI_POST=%i")" = 1 ]&&grep "^Environment=" $T/u|grep -q "PATH=/var/lib/agi/%i/bin"&&[ "$(grep -c AGI_SEAT $T/u)" = 0 ]'
nec=$(grep -c '^ExecCondition=' $T/u);ec=$(grep '^ExecCondition=' $T/u|head -1)
ug=$(sed -n "s/^ExecCondition=sh -c '\(.*\)'\$/\1/p" $T/u);g1=$(H=claude-x sh -c "$ug" 2>/dev/null;echo $?);g2=$(H='node /opt/pi/pi --provider x -e ../bin/cccc.ts' sh -c "$ug" 2>/dev/null;echo $?);g3=$(env -u H sh -c "$ug" 2>$T/g3.err;echo $?);g4=$(H= sh -c "$ug" 2>$T/g4.err;echo $?)
ok "f3-exec-condition-gates-on-claude-and-has-no-brace the unit has $nec ExecCondition (want 1) [$ec] and holds $(grep -c '\${' $T/u) '\${' (want 0: systemd substitutes \${H} with the spaced value of a pi post)" '[ "$nec" = 1 ]&&[ -n "$ug" ]&&[ "$(grep -c "\${" $T/u)" = 0 ]'
ok "f3-exec-condition-three-states a claude H exits $g1 (want 0), a set H that is not claude (a pi post's 'node ...') $g2 (want 2: the skip, no double wake), an UNSET H $g3 and an EMPTY H $g4 (want 255 both, with '[boxwake] H unset' on stderr: a unit that cannot tell its harness FAILS and is seen, it does not skip silently)" '[ "$g1" = 0 ]&&[ "$g2" = 2 ]&&[ "$g3" = 255 ]&&[ "$g4" = 255 ]&&grep -qF "[boxwake] H unset" $T/g3.err&&grep -qF "[boxwake] H unset" $T/g4.err'
ok "f3-loop-box-n-is-bounded the ExecStart runs $(grep '^ExecStart=' $T/u|grep -c '$(timeout 20 box n ') '\$(timeout 20 box n ' (want 1): systemd re-spawns a DEAD loop, not a STUCK one, so a hung box must not stall the loop for good" '[ "$(grep "^ExecStart=" $T/u|grep -c "\$(timeout 20 box n ")" = 1 ]'
xs=$(grep '^ExecStart=' $T/u);ck=$(printf '%s\n' "$xs"|grep -c ')||continue;p=$f;n=');cs=$(printf '%s\n' "$xs"|grep -c 'continue;p=\$f;n=.*;s=\$n;done')
ok "f3-loop-keeps-s-on-a-failed-count a failed count (timeout's status 124, or any non-zero status of box n) CONTINUES before p or n is set and before s=\$n: $ck line(s) with '\$(timeout 20 box n ...)||continue;p=\$f;n=' (want 1), $cs with s=\$n after it (want 1). Else a hang sets n=0 and s=0 and the next good tick re-types the wake for mail already announced (council remark, 11:46Z); p stays, so the next tick tries again (goal:g7.16.1.11.32 B)" '[ "$ck" = 1 ]&&[ "$cs" = 1 ]'
fp=$(printf '%s\n' "$xs"|grep -c 'f=\$(git for-each-ref refs/box refs/held/\$AGI_POST 2>&1|cksum);k=\$((k+1));\[ "\$f" = "\$p" \]&&\[ \$k -lt 12 \]&&continue;k=0;o=\$(timeout 20 box n ')
ok "f3-loop-fingerprints-the-refs-before-box-n the ExecStart reads one 'git for-each-ref refs/box refs/held/\$AGI_POST' checksum per tick and runs box n only when it changed or every 12th tick: $fp line(s) with the whole shape (want 1); it holds no '%(' (systemd would read a specifier) and no '\${' ($(grep '^ExecStart=' $T/u|grep -c '%(\|\${')), want 0)" '[ "$fp" = 1 ]&&[ "$(grep "^ExecStart=" $T/u|grep -c "%(\|\\\${")" = 0 ]'
dr=;for w in $(grep '^Environment=' $T/u|sed 's/^Environment=//'|tr ' ' '\n'|grep -v '^AGI_POST=');do grep '^Environment=' $T/p|sed 's/^Environment=//'|tr ' ' '\n'|grep -qxF -- "$w"||dr="$dr [$w]";done
ok "f3-unit-environment-words-equal-the-posts every Environment= word of the wake unit except AGI_POST=%i (PATH, SHELL, GIT_*) is also a word of agi-post@'s Environment= lines; drifted:${dr:- none} (want none): the two units re-type the same words, and a drift would run the loop in another env than its post" '[ -z "$dr" ]'
ok "f3-post-unit-wants-the-wake-unit agi-post@.service holds Wants=agi-boxwake@%i.service in its [Unit] ($(awk '/^\[Unit\]/{u=1;next} /^\[/{u=0} u&&/^Wants=agi-boxwake@%i.service$/' $T/p|wc -l|tr -d ' ') line, want 1)" '[ "$(awk "/^\\[Unit\\]/{u=1;next} /^\\[/{u=0} u&&/^Wants=agi-boxwake@%i.service\$/" $T/p|wc -l|tr -d " ")" = 1 ]'
nl=$(grep -c "box n" $T/u);nr=$(grep -c "box n" $T/ar);nw=$(grep '^ExecStart=' $T/u|grep -c 'while :;do sleep 5||:;')
ok "f4a-one-box-loop-in-the-unit-and-none-in-agi-run the unit has $nl line(s) with 'box n' (want 1) and its loop is 'while :;do sleep 5||:;' ($nw, want 1); the agi-run piece has $nr (want 0: no double wake). The cccc.ts interval is the pi route's own and is not counted" '[ "$nl" = 1 ]&&[ "$nw" = 1 ]&&[ "$nr" = 0 ]'
nh=$(cat $G/engine-root.md $G/engine-wrap.md|grep -ci heartbeat)
ok "f5-no-heartbeat-and-no-checker engine-root.md and engine-wrap.md hold $nh 'heartbeat' (want 0)" '[ "$nh" = 0 ]'
echo "boxwake-unit: $f FAIL"
exit $f
